وقوله: ﴿وَهُوَ شَهِيدٌ﴾ أي: شاهد القلب حاضر غير غائب.
قال ابن قيّم: "اسمع كتاب الله، وأنت شاهد القلب والفهم، غير غائب.

بغافل ولا ساهٍ. وهو إشارةٌ إلى المانع من حصول التأثير، وهو سهْو
القلب وغفلته عن تعقل ما يقال له، والنظر فيه وتأمله.

فإذا حصل المؤثّر - وهو القرآن، والمحلّ القابل - وهو القلب الـ ـحي،
والشرط - وهو الإصغاء، وانتفى المانع - وهو اشتغال القلب وذهوله
عن معنى الخطاب، وانصرافه عنه إلى شيء آخر؛ حصل الأثر وهو
الانتفاع والتذكرة.

فإن قيل: إذا كان التأثير إنما يتمّ بمجموع هذه، فما وجه دخول أداة
(أو) في قوله: ﴿أَوْ أَلْقَى السَّمْعَ﴾؟ والموضوع موضوع واو للجمع لا أو
التي هي لأحد الشيئين؟

قيل: هذا سؤال جيّد، والجواب عنه أن يقال: خرج الكلام (أو)
باعتبار حال المخاطَب المدعوّ:

فإنّ من الناس من يكون حيّ القلب، واعيًا، تامَّ الفِطْرَة؛ فإذا
تُلي عليه القرآن، وجَّه قلبه وسمعه، وتلقّى بقبوله وعقله معنى
القرآن، فأثّر فيه تأثيرًا عجيبًا. فهذا حال من حصل فيه شرط التأثير
وأسبابه كلها.

فأمّا إذا كان القلب غيرَ تام الفطرة، وكان فيه نوع ضعف؛
احتاج إلى أن يُوجّه سمعه، ويُصغي بسمعه إلى ما يقال له، فيتحقق في
