وأمر آخر: أن يعلم من ذنوبهم وعيوبهم ما لا يعلمونه من نفوسهم، فيأتيهم المكر من حيث لا يشعرون.

وأمر آخر: أن يمتحنهم ويسلمهم لما صبر لهم عليه، فيفتنهم به، وذلك مكر.

وبالله التوفيق.""",
  ),
  Fwaid(
    id: '96',
    name: """ فصل""",
    text: """خُلِق بدن ابن آدم من الأرض وروحه من ملكوت السماء، وقُرِن بينهما:

فإذا أُجاع بدنه وأُسهره وأقامه في الخدمة وجدت روحه خفّةً وراحةً، فاشتاقت إلى الموضع الذي خُلِقَت منه، وسافرت إلى عالمها العلوي، وإذا أشبعه ونعّمه وقوّته اشتغل بخدمته وراحة البدن إلى الموضع الذي خُلِقَ منه، فانجذبت روحه معه، فصارت في سجن؛ فلو أنها أُلقيت السجن لم تستأنس من ألم مغارزها وانقطاعها عن عالمها الذي خُلِقَت منه كما يستأنف المُعذَّب.

وبالجملة كلما خفّ البدن لطفت الروح وخفّت وطلبت عالمها العلوي، وكلما ثقل وأخلد إلى الشهوات والراحة ثقلت الروح وجُعلت من عالمها وصارت أرضيّة سُفليّة.

فترى الرجل روحه في الرفيق الأعلى وبدنه عندك، فيكون نائمًا على فراشه وروحه عند سدرة المنتهى تجول حول العرش، وآخر واقف في الخدمة ببدنه وروحه في السفل تجول حول السُّفليّات.

فإذا فارق الروح البدن استقرّت برفيقها الأعلى أو الأدنى؛ فعند الرفيق الأعلى كل نعيم وسرور وراحة ولذّة طيّبة، وعند الرفيق الأسفل كل همّ وغمّ وضيق وحزن وحياة كدّة ومعيشة ضنك.

قال تعالى: ﴿وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكًا﴾ [طه/١٢٤]، وذكره كلامه الذي أنزله على رسوله، والإعراض عنه ترك تدبّره والعمل به، والمعيشة الضنك ما جاء في التفسير: أنها عذاب القبر. قاله ابن مسعود وأبو هريرة وأبو سعيد الخدري وابن عباس. وفيه حديث مرفوع. (٢)

وقيل: هي في الدنيا. وقيل: منزل ضنك وعيش ضنك. وهذه الأقوال متلازمة؛ فالضنك في مقابلة السعة. قال: منزل ضنك وعيش ضنك. فكل ما ضاق على النفس والبدن بالشهوات واللذّات والراحة؛ فإن النفس كلما وسّعت عليها ضيّقت على القلب حتى تصير معيشته ضنكًا، وكلما ضيّقت عليها وسّعت على القلب حتى ينشرح وينفسح؛ فضيق المعيشة في الدنيا بموجب التقوى سعتها في الرزق والآخرة، وسعة المعيشة في الدنيا بحكم الهوى ضيقها في الرزق والآخرة.

فأثّر أحسن المعيشتين وأطيبها وأدومها، وأنعم البدن بنعيم الروح، فإن نعيم الروح وشقاءها أعظم وأدوم، ونعيم البدن وشقاءه أقصر وأهون.

والله المستعان. """,
  ),
  Fwaid(
    id: '97',
    name: """فصل """,
    text:
        """ العارف لا يأمر الناس بترك الدنيا؛ فإنهم لا يقدرون على تركها، ولكن يأمرهم بترك الذنوب مع إقامتهم في الدنيا؛ فإن ترك الذنوب فريضة، وترك الدنيا فضيلة، والفضيلة من المفرِض.

فإن صعب عليهم ترك الذنوب، فاجتهد أن تُحبِّبَ الله إليهم بذكر آلائه وإنعامه وإحسانه وصفات كماله ونعوت جلاله؛ فإن القلوب مفطورة على محبته؛ فإذا تعلقت بحبه هان عليها ترك الذنوب والاستقلال منها والإصرار عليها.

وقد قال يحيى بن معاذ: طلب العاقل للدنيا خير من ترك الجاهل لها.

العارف يدعو الناس إلى الله من دنياهم فتسهل عليهم الإجابة، والزاهد يدعوهم إلى الله بترك الدنيا فتشق عليهم الإجابة؛ فإن الفطام عن الذي علق به عقل الإنسان نفسه، لا وهو يرتفع منه شأناً، ولكن خير من رضاع المرء الحمصي بعودٍ يقطع اللثة.

وقيل: المرء الحمقي يعود بحب الولد، إنما كان رضاعه من المجاعة؛ فإن قويت على مرارة الفطام فارضع بقدره، فإن اليتيم ما يقل.""",
  ),
  Fwaid(
    id: '98',
    name: """ فصل""",
    text: """بين رعاية الحقوق مع الضرر ورعايتها مع العافية بون بعيد.

إن عبدي ـ كل عبدي ـ الذي يذكرني وهو ملاقٍ قرنه. (١)

﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا لَقِيتُمْ فِئَةً فَاثْبُتُوا وَاذْكُرُوا اللَّهَ كَثِيرًا لَعَلَّكُمْ تُفْلِحُونَ﴾ [الأنفال/٤٥].

ليس المحب من صحيح فارغ واقف مع الخدمة، إنما المحب ضعيف تقوّيه الأشياء وتختلف عليه الأحوال وقلبه واقف في الخدمة غير مختلف بما يقدر عليه. """,
  ),
  Fwaid(
    id: '99',
    name: """ فصل""",
    text: """معرفة الله سبحانه نوعان:

الأول: معرفة إقرار، وهي التي اشترك فيها الناس: البر والفاجر، والمطيع والعاصي.

والثاني: معرفة توجب الحياء منه، والمحبة له، وتعلق القلب به، والشوق إلى لقائه، وخشيته والإنابة إليه، والأُنس به والفرار من الخلق إليه.

وهذه هي المعرفة الخاصة الجارية على لسان القوم، وتفاوتهم فيها يخصه إلا الذي عرّفهم بنفسه وكشف لقلوبهم من معرفته ما أخفاه عن سواهم، وكلٌّ أشار إلى هذه المعرفة بحسب مقامه وما كُشِف له منها.

وقد قال أعرف الخلق به: «لا أُحصي ثناءً عليك أنت كما أثنيت على نفسك» (١)، وأخبر أنه سبحانه يفتح عليه يوم القيامة من محامده بما لم يُحسنه الآن.

ولهذه المعرفة بابان واسِعان:

باب الأول: التفكّر والتأمّل في آيات القرآن كلها [١٩١]، والفهم الخاص عن الله ورسوله.

والباب الثاني: التفكّر في آياته المشهودة، وتأمّل حكمته فيها وقدرته ولطفه وإحسانه وعدله وقيامه بالقسط على خلقه.

وجماع ذلك: الفقه في معاني أسمائه الحسنى وجلالها وكمالها وقدره بذلك وتعلّقها بالخلق والأمر، فيكون فقيهًا في أوامره ونواهيه، فقيهًا في قضائه وقدره، فقيهًا في أسمائه وصفاته، فقيهًا في الحكم الديني الشرعي والحكم الكوني القدري، وهو ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم [الحديد/٢١]. """,
  ),
  Fwaid(
    id: '100',
    name: """ فصل""",
    text:
        """ الدراهم أربعة: درهم اكتسب بطاعة الله وأُخرج في حقِّ الله؛ فذاك خيرُ الدراهم، ودرهم اكتسب بمعصية الله وأُخرج في معصية الله؛ فذاك شرُّ الدراهم، ودرهم اكتسب بأذى مسلم وأُخرج في أذى مسلم؛ فهو كذلك، ودرهم اكتسب بمباح وأنفق في شهوة مباحة؛ فذاك لا له ولا عليه.

(١) قطعة من حديث أخرجه مسلم (٤٨٦) عن عائشة.

٢٤٩

هذه أصول الدراهم، ويتفرّع عليها دراهم أُخر؛ منها: درهم اكتسب بحق وأنفق في باطل، ودرهم اكتسب بباطل وأنفق في حق؛ ففائدة هذا كفّارة، ودرهم اكتسب من شبهة؛ فكفارته أن ينفق في طاعة.

وكما يتعلق الثواب والعقاب والمدح والذم بإخراج الدرهم؛ فكذلك يتعلق باكتسابه.

وكذلك يُسأل عن مخرجه ومصرفه: من أين اكتسبه؟ وفيما أنفقه؟ (١)""",
  ),
  Fwaid(
    id: '101',
    name: """فصل """,
    text:
        """المواساة للمؤمنين أنواع: مواساة بالمال، ومواساة بالجاه، ومواساة بالبدن والخدمة، ومواساة بالنصيحة والإرشاد، ومواساة بالدعاء والاستغفار لهم، ومواساة بالتوجع لهم.

وعلى قدر الإيمان تكون هذه المواساة؛ فكلما ضعف الإيمان ضعفت المواساة، وكلما قوي قويت.

وكان رسول الله ﷺ أعظم الناس مواساةً لأصحابه بذلك كله؛ فأتباعه من المواساة بحسب اتباعهم له.

ودخلوا على بشر الحافي في يوم شديد البرد، وقد تجرد، وهو ينتفض؛ فقالوا: ما هذا يا أبا نصر؟ فقال: ذكرت الفقراء وبردهم، وليس لي ما أواسيهم به، فأحببت أن أواسيهم ببردهم. """,
  ),
  Fwaid(
    id: '102',
    name: """فصل """,
    text:
        """ الجهل بالطريق وآفاتها والمقصود يوجب التعب الكثير مع الفائدة القليلة؛ فإن صاحبه إما أن يجتهد في نافلة مع إضاعة الفرض، أو في عمل بالجوارح لم يواطئه عمل القلب، أو عمل بالباطن والظاهر لم يقيده بالاقتداء، أو همه إلى عمل لم تُرقَ صاحبها إلى ملاحظة المقصود، أو عمل لم يجزه عن آفة مفسدة لعمله وعدوه، أو عمل غفل عن مشاهدة المنة فيه فيخرج عن مشاركة النفس فيه، أو عمل فيه تقصير فيقوم بعده في مقام الاعتذار منه، أو عمل لم يوقَّ حقه من النصح والإحسان وهو يظن أنه وفاه؛ فأقل ذلك مما ينقص الثمرة مع كثرة التعب. والله الموفق.""",
  ),
  Fwaid(
    id: '103',
    name: """ فصل""",
    text:
        """ إذا عزم العبد على السفر إلى الله تعالى وإرادته عرضت له العوائق والقواطع، فينجذب أولًا بالشهوات والرئاسات والملاذ والمناكح والملابس. فإن وقف معها انقطع، وإن رفضها ولم يقف معها وصدق في طلبه ابتلي بوطء عقبه وتقبيل يده والتوسعة له في المجلس والإشارة إليه بالدعاء ووجاهة مركته ونحو ذلك. فإن وقف معها انقطع، مع أن الله كان حظه من ذلك قطعته، وإن رفضها ابتلي بالإكرامات والكشوفات. فإن وقف معها انقطع، وإن لم يقف معها وكانت حظه بها من الله التجريد والتخلي ولذة الجمعية وعزة الوحدة والفراغ من الدنيا، فقد وقع معه ذلك انقطع به عن المقصود، ولم يقف معه وسار ناظرًا إلى مراد الله منه وما يحبه منه؛ بحيث يكون عبده الموقوف على محابه [١٨٦] ومراضيه أين كانت وكيف كانت؛ تعب بها أو استراح.

٢٥١

تعب أو تله، أو أُحْجِب إلى الناس أو غاب عنهم، لا يختار لنفسه غير ما يختاره له وليه وسيده، واقف مع أمر ربه بحسب الإمكان، ونفسه عنده أهون عليه من أن يقدم راحته ولذتها على مرضاة سيده وأمره؛ فهذا هو العبد الذي قد وصل ونفذ ولم يقطعه عن سيده شيء البتة. وبالله التوفيق.""",
  ),
  Fwaid(
    id: '104',
    name: """ فصل""",
    text:
        """النِّعَم ثلاثة: نعمة حاصلة يعلم بها العبد، ونعمة منتظرة يرجوها، ونعمة هو فيها لا يشعر بها.

فإذا أراد الله إتمام نعمته على عبده عرّفه نعمة الحاضرة وأعانه من شكرها قيدًا يقيدها به حتى لا تشرد؛ فإنها تشرد بالمعصية وتُقَيَّد بالشكر، ووفقه لعمل يستجلب به النعمة المنتظرة، وبصّره بالطرق التي تُسدُّها وتقطع طريقها ووفقه لاجتنابها، وإذا بلغ به ذلك إلى أتم الوجوه، وعرّفه النعمة التي هو فيها لا يشعر بها.

ويُحكى أن أعرابيًّا دخل على الرشيد، فقال: أمِرِ المؤمنين! أنشدك الله النِّعم التي أنت فيها باطنة تكرهها، وحقِّ النِّعم التي ترجُوها، والظنَّ ودوامها؛ أن تعرف النِّعم التي أنت فيها ولا تعرف شكرها. فأعجبه ذلك منه وقال: أحسنتَ تقسيمًا! """,
  ),
  Fwaid(
    id: '105',
    name: """قاعدة جليلة """,
    text:
        """مبدأ كل علم نظري وعمل اختياري هو الخواطر والأفكار؛ فإنها توجب التصورات، والتصورات تدعو إلى الإرادات، والإرادات تقتضي وقوع الفعل، وكثرة تكراره تعطي العادة.

فصلاح هذه المراتب بصلاح الخواطر والأفكار، وفسادها بفسادها.

صلاح الخواطر بأن تكون مراقِبة لوليها وإلهها، صاعدة إليه، دائرة على مرضاته ومحبته؛ فإنه سبحانه به كل صلاح، ومن عنده كل هدى، ومن توفيقه كل رشد، ومن توليه لعبده كل حفظ، ومن توليه وإعراضه عنه كل ضلال وشقاء.

فأفضل الخواطر وأجلها وأعلاها: فكرة في آلاء الله ونعمه وتوحيده، وطرق معرفته وطرق عبوديته، وإزالة إيحاشه حاضرًا معه، مشاهدًا له ناظرًا إليه، رقيبًا عليه مطلعًا على خواطره وإراداته وهمه؛ فحينئذ يستحيي منه ويجله ويعظمه على عورة يكره أن يطلع عليه مخلوق مثله، أو يرى في نفسه خاطرًا يمقته عليه.

فمتى أنزل ربه هذه المنزلة من رفعه وقربه منه وأكرمه واجتباه وولاه، وقدر ذلك يبعده عن الأوساخ والدناسات والخواطر الردية والأفكار الدنية، كما أنه كلما بعد عنه قرب من الأوساخ والدناسات والأذى، وانقطع عن جميع الكمالات واتصل بجميع النقائص.

فالإنسان خير المخلوقات إذا اقترب من باريه والتزم أوامره ونواهيه وعمل برضاه، وأثره على هواه، وشر المخلوقات إذا تباعد عنه ولم يتحرك قلبه لقربه وطاعته وابتغاء مرضاته؛ فمتى اختار التقرب إليه وأثره على نفسه وهواه فقد حكم قلبه وعقله وإيمانه على نفسه وشيطانه، وحكم رشده على غيه وهداه على هواه، ومتى اختار البعد منه فقد حكم نفسه وهواه وشيطانه على عقله وقلبه ورشده.

واعلم أن الخطرات والوساوس تؤدي متعلقاتها إلى الفكر، فيأخذها الفكر فيؤديها إلى الذكر، فيأخذها الذكر فيؤديها إلى الإرادة، فيأخذها الإرادة فيؤديها إلى الجوارح والعمل، فتستحكم تصير عادة، فردها من مبادئها أسهل من قطعها بعد قوتها وتمامها.

ومعلوم أنه لم يُعطَ الإنسان إماتة الخواطر ولا القوة على قطعها؛ فإنها تهاجم عليه هجوم النفس؛ إلا أن قوة الإيمان والعقل تعينه على قبول ما يرضاه ومساهلة ما يكرهه، وعلى دفع ما لا يرضاه؛ كما في الحديث الصحيح: يا رسول الله! إنا نجد في أنفسنا ما لأن نخرق حتى نصير حمما أحب إلينا من أن نتكلم به؟ فقال: «أوقد وجدتموه؟» قالوا: نعم. قال: «ذاك صريح الإيمان». (١)

وفي لفظ: «الحمد لله الذي رد كيده إلى الوسوسة». (٢)

وفيه قولان:

أحدهما: أن رده وكراهته صريح الإيمان.

والثاني: أن وجوده وإلقاء الشيطان له في النفس صريح الإيمان؛ فإنه إنما ألقاه في النفس طلبًا لمعارضة الإيمان وإزالته.

وقد خلق الله سبحانه النفس شبيهة بالرحى الدائرة التي لا تسكن ولابد لها من شيء تطحنه؛ فإن وضعت فيها حبًّا طحنته، وإن وضعت فيها ترابًا أو حصى طحنته. فالأفكار والخواطر التي تجول في النفس بمنزلة الحب الذي يوضع في الرحى، ولا تبقى تلك الرحى معطلة قط؛ بل لابد لها من شيء يوضع فيها؛ فمن الناس من تطحن حبًّا جيدًا يخرج دقيقًا ينتفع به نفسه وغيره، وأكثرهم يطحن رملًا وحصى وتبنًا ونحو ذلك؛ فإذا جاء وقت العجن والخبز تبين له حقيقة طحنه. """,
  ),
  Fwaid(
    id: '106',
    name: """فصل """,
    text: """من لم يعرف نفسه كيف يعرف خالقه؟

فاعلم أن الله تعالى خلق في صدرك بيتًا وهو القلب، ووضع في صدره عرشًا لمعرفته يستوي عليه المثل الأعلى؛ فهو مستوٍ على عرشه بذاته بائن من خلقه، والمثل الأعلى من معرفته ومحبته وتوحيده مستوٍ على سرير القلب، وعلى سرير البسط من الأرض، ووضع عن يمينه وشماله مرافق شرائعه وأوامره، وفتح إليه بابًا من جهة رحمته والأنس به والشوق إلى لقائه، وأطهر من وراء ذلك كله ما به من أصناف الثمر والأشجار المثمرة من الطاعات والتهليل والتسبيح والتحميد والتقديس، وجعل وسط البستان شجرة معرفة: ﴿تُؤْتِي أُكُلَهَا كُلَّ حِينٍ بِإِذْنِ رَبِّهَا﴾ [إبراهيم/٢٥] من المحبة والإنابة والخشية والفرح والابتهاج بقربه، وأجرى إلى تلك الشجرة ما يسقيها من تدبير كلامه وفهمه والعمل بوصاياه، وعلق في ذلك البيت قنديلًا أسرجه بضياء معرفته والإيمان به وتوحيده؛ فهو يستمد من شجرة مباركة زيتونة: ﴿لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ﴾ [النور/٣٥] يضيء ولو لم تمسسه نار، فأحاط عليه بلائحة آدم، وأقام عليه حرسًا من الملائكة يحفظونه في يقظته ومنامه.

ثم أعلم صاحب البيت والبستان الساكن فيه؛ فهو دائمًا همه إصلاح السكن، ولم يشغله لرضاه الساكن منزلًا، وإذا أحسن بآذى سعت إصلاحه، وله خشية انتقال الساكن منه؛ فنعم الساكن والمسكن.

فسبحان الله رب العالمين! كم في هذا البيت وبيت قد استولى عليه الخراب، وصار مأوى للحشرات والهوام، ومحلًّا لإلقاء الأقذار، ومنبعًا للنجاسات؛ فترى صاحب هذا البيت لا يجد راحة للساكن فيها ولا حافظًا له، وهي أدنى لحاجته، مظلمة الأرجاء، لا يأنس ولا يزال ينزل فيها إلا من يناسب سكانها من الحشرات والديدان والهوام؛ الشيطان جالس على سريرها، وعلى سرير البسط من الجهل، ويحقق الأهواء، ويزين له شهواته واتباع الهوى، وقد فتح له بابًا من جهة الخبث والوحشة والركون إلى الدنيا والطمأنينة والزهد فيها، وأطفأ نور المصباح وأدخل فيه أنواع الشوك والحطب والأشجار المثمرة بأنواع المعاصي والمخالفات، من الزوائد والتبدينات والنودرات والهزليات والمضحكات والأشعار والغزليات والخمريات التي تهجم على ارتكاب المحرمات، وترفض في الطاعات، وجعل وسط الحقل شجرة الجهل والإعراض عنه؛ فهي تؤتي أكلها كل حين من الفسوق والمعاصي واللهو واللعب والمجون والذنوب مع كل ريح وإتباع كل شهوة، ومن ثمرها الهموم والغموم والأحزان والآلام، لكنها متوارية باستقبال النفس بهواها ولعبها؛ فإذا التفت من سكرها أحضرت كل هم وغم وحزن وقلق ومصيبة، وأجرى إلى تلك الشجرة ما يسقيها من اتباع الهوى وطول الأمل والغرور، فأثمرت بطالة وخرابًا وجفافًا بحيث لا يُنتفع منه مفيد ولا حيوان ولا مؤذٍ ولا يُقدَر.

فسبحان خالق هذا البيت وذاك البيت!

فمن عرف قدر بيته وقدر الساكن فيه وقدر ما فيه من الكنوز والذخائر والآلات؛ انتفع بحياته ونفسه، ومن جهل ذلك جهل نفسه وأضاع سعادته.

وبالله التوفيق. """,
  ),
  Fwaid(
    id: '107',
    name: """فصل """,
    text:
        """سهل بن التستري: الرجل يأكل في اليوم أكلة؛ قال: أكل الصديقين. قيل له: فأكلتين؟ قال: أكل المؤمنين. قيل له: فثلاث؟ قال: هل لأهله يتناول له معلفًا.

قال الأسود بن سالم: ركعتين أصليهما أنا أحب إليَّ من الجنة بما فيها. فقيل له: هذا حظ. فقال: خذوا من كلامكم، الجنة رضي الله عني ورضي ربي عني.

(١) كذا في الأصل منصوبًا.

٢٦١

نفسي، والركعتان رضي ربي، ورضي ربي أحب إليَّ من رضي نفسي.

العارف في الأرض ريحانة من رياحين الجنة، إذا شمها المريد اشتاقت نفسه إلى الجنة.

قلب المحب موضوع بين جلال محبوبه وجماله؛ فإذا لاحظ جلاله هابه وعظمته، وإذا لاحظ جماله أحبه واشتاق إليه. """,
  ),
  Fwaid(
    id: '108',
    name: """ فائدة""",
    text:
        """ من الناس من يعرف الله بالجود والإفضال والإحسان، ومنهم من يعرفه بالعفو والحلم والتجاوز، ومنهم من يعرفه بالبطش والانتقام، ومنهم من يعرفه بالعلم والحكمة، ومنهم من يعرفه بالعزة والكبرياء، ومنهم من يعرفه بالرحمة والبر واللطف، ومنهم من يعرفه بالقهر والملك، ومنهم من يعرفه بإجابة الدعاء عند الشدة وقضاء الحاجة.

واعلم هؤلاء كلهم معرفة من كلامه؛ فمن عرفه من كلامه اجتمعت صفات الكمال ونعوت الجلال مبرأة عن المثال، بريئة من النقائص والعيوب، له كل اسم حسن، وكل وصف كمال، فعال لما يريد، فوق كل شيء، ومع كل شيء، وقادر على كل شيء، ومقيم لكل شيء، أمره نافذ، متكلم بكلمته الدينية والكونية، أكبر من كل شيء، وأجمل من كل شيء، أرحم الراحمين، وأقدر القادرين، وأحكم الحاكمين.

فالقرآن أنزل لتعريف عباده به، وبصراطه الموصل إليه، وجزاء السالكين بعد الوصول إليه.""",
  ),
  Fwaid(
    id: '109',
    name: """فائدة """,
    text: """من الآفات الخفية العامة أن يكون العبد في نعمة أنعم الله بها عليه

٢٦٢

واختارها له، فيميلها العبد ويطلب الانتقال منها إلى ما يزعم لجهله أنه خيرٌ له منها، ورُبَّةُ رحمته لا يُخرجه من تلك النعمة ويقدِّره بجهله وسوء اختياره لنفسه، حتى إذا أضاف ذرًّا تلك النعمة وسخطها وتبرُّم بها واستحكم ذلك منه، سلبها منه ابتلاءً؛ ليُعرِّفه ما له وما طلبه، ويرى التفاوت بين ما كان فيه وما صار إليه؛ ليتبين له فضل ما فارقه وعلو درجته عليه.

فإذا أراد الله بعبده خيرًا، أشهده أن ما هو فيه نعمةٌ عليه، ورضَّاه به وأوزعه شكره عليه؛ فإذا حدَّثته نفسه بالانتقال عنه استخارةَ ربِّه استخارةَ جاهلٍ بمصلحته عاجزٍ عنها مفوِّضٍ إلى الله طالبٍ منه حسن اختياره له.

وليس على العبد أضرّ من مِلْكِه لنعم الله؛ فإنه إذا رآها نعمةً ولا يشكرها عليها ولا يفرح بها، بل يسخطها ويشكوها ويعدّها مصيبة، فهذا وهي من أعظم نعم الله عليه.

فانظر الناس أعداء نعم الله عليهم، ولا يشعرون بفتح الله عليهم بنعمه، وهم مجتهدون في دفعها وردِّها جهلًا وظلمًا؛ فكم سعت إلى أحدهم من نعمة وهو ساعٍ في ردِّها بجهله، وكم وصلت إليه وهو ساعٍ في دفعها وزوالها بظلمه وجهله!

قال تعالى: ﴿ذَلِكَ بِأَنَّ اللَّهَ لَمْ يَكُ مُغَيِّرًا نِعْمَةً أَنْعَمَهَا عَلَى قَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنْفُسِهِمْ﴾ [الأنفال/٥٣].

وقال تعالى: ﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنْفُسِهِمْ﴾ [الرعد/١١].

فليس للنعيم أعدى من نفس العبد؛ فهو مع عدوه ظهيرٌ على نفسه.

٢٦٣

وعدوُّه يطرح [١٩٤] النار في نعمه وهو يفتح فيها؛ فهو الذي مكَّنه من طرح النار ثم أعانه بالنفخ؛ فإذا اشتد ضرامها استغاث [من] الحريق، وكان غاية معاناة الأقدار:

وعاجزُ الرأي مضيِّعٌ لفرصته
حتى إذا فات أمرٌ عاتبَ القدرَ. """,
  ),
  Fwaid(
    id: '110',
    name: """فصل """,
    text:
        """من أعز أنواع المعرفة معرفة الرب سبحانه بالجمال، وهي معرفة خواص الخلق، وكلهم عرفه بصفة من صفاته، وأتمهم معرفة من عرفه بكماله وجلاله وجماله، سبحانه ليس كمثله شيء في سائر صفاته.

ولو فرضت الخلق كلهم على أجملهم صورة، وكلهم على تلك الصورة، ونسبت جمالهم الظاهر والباطن إلى جمال الرب سبحانه؛ لكان أقل من نسبة سراج ضعيف إلى قرص الشمس.

ويكفي في جماله أنه لو كشف الحجاب عن وجهه لأحرقت سبحات وجهه ما انتهى إليه بصره من خلقه. (١)

ويكفي في جماله أن كل جمال ظاهر وباطن في الدنيا والآخرة فمن آثار صنعته؛ فما الظن بمن صدر عنه هذا كله؟!

ويكفي في جماله وحسنه القوة كلها، والغنى كله، والجود كله، والإحسان كله، والعلم كله، والفضل كله، ولنور وجهه أشرف الظلمات؛ كما قال النبي ﷺ في دعاء الطائف: «أعوذ بنور وجهك الذي أشرقت له الظلمات، وصلح عليه أمر الدنيا والآخرة». (٢)

وقال عبد الله بن مسعود: (٣): ليس عند ربكم ليل ولا نهار؛ نور السماوات والأرض من نور وجهه، فهو سبحانه نور السماوات والأرض، ويوم القيامة إذا جاء لفصل القضاء أشرقت الأرض بنوره.

ومن أسمائه الحسنى: الجميل.

وفي الصحيح عنه ﷺ: «إن الله جميل يحب الجمال». (٣)

وجماله سبحانه على أربعة مراتب: جمال الذات، وجمال الصفات، وجمال الأفعال، وجمال الأسماء؛ فالأسماء كلها حسنى، وصفاته كلها صفات كمال، وأفعاله كلها حكمة ومصلحة وعدل ورحمة. وأما جمال الذات فما هو عليه فأمر لا يدركه سواه ولا يعلمه غيره، وليس عند المخلوقين منه إلا تعريفات تعرف بها إلى من أكرمه من عباده؛ فإن ذلك الجمال مصون عن الأغيار، محجوب بسر الرداء والإزار؛ كما قال رسوله ﷺ فيما يحكي عن ربه: «الكبرياء ردائي، والعظمة إزاري». (٤) وما كانت الكبرياء أعظم وأوسع كانت أحق باسم الرداء؛ فإنه سبحانه الكبير المتعال، فهو سبحانه العلي العظيم.

قال ابن عباس: حب الذات بالصفات، وحب الصفات بالأفعال؛ فما ذاك بجمال بأوصاف الكمال، وسير بنعوت العظمة والجلال؟!

ومن هذا المعنى يفهم بعض معاني جمال ذاته؛ فإن العبد يرتقي من معرفة الأفعال إلى معرفة الصفات، ومن معرفة الصفات إلى معرفة الذات؛ فإذا شاهد شيئًا من جمال الأفعال استدل به على جمال الصفات، ثم استدل بجمال الصفات على جمال الذات.

ومن هنا ما يتبين أنه سبحانه له الحمد كله، وأن أحدًا من خلقه لا يحصي ثناءً عليه، بل هو كما أثنى على نفسه، وأنه يستحق أن يُعبد لذاته ويُحب لذاته ويُشكر لذاته، وأنه سبحانه يحب نفسه ويثني على نفسه ويحمد نفسه، وأن محبته لنفسه وحمده لنفسه وثناؤه على نفسه وتوحيده لنفسه هو عين حقيقة الحمد والحب والتوحيد؛ فسبحانه كما أثنى على نفسه، ويحب صفاته وأفعاله؛ فكل أفعاله حسن (١٩٤) محبوب، وإن كان في مفعولاته ما يبغضه ويكرهه؛ فليس في أفعاله ما هو مكروه مسخوط، وليس في الوجود ما يُحب لذاته ويُحمد لذاته إلا هو سبحانه، وكل ما يُحب سواه فإنما يُحب تبعًا لمحبته سبحانه، بحيث يُحب لأجله، ومحبة صحيحة لغيره محبة باطلة، وهذا معنى حقيقة «لا إله إلا الله» الذي يُحب لذاته ويُحمد لذاته. فكيف لا يُضاف إلى ذلك إحسانه وإنعامه وحلمه وتجاوزه وعفوه وبره ورحمته؟!

فعلى العبد أن يعلم أنه لا إله إلا الله فيحبه ويحمده لذاته وكماله، وأن يعلم أنه محسن على الحقيقة بأصناف النعم الظاهرة والباطنة؛ فهو يُحبه لإحسانه وإنعامه ويحمده على ذلك، فيحبه من الوجهين جميعًا.

وكما أن ليس كماله شيء، فليس كمحبته محبة.

والمحبة مع الخضوع هي العبودية التي خُلق الخلق لأجلها؛ فإنها غاية الحب بغاية الذل، ولا يصلح ذلك إلا له سبحانه، والإشراك به في هذا هو الشرك الذي لا يغفره الله ولا يقبل لصاحبه عملًا.

وحمده يتضمن أصلين: الإخبار بمحاسنه وصفات كماله، والمحبة له عليها؛ فمن أخبر بمحامده من غير محبة لم يكن حامدًا، ومن أحبه من غير إخبار بمحامده لم يكن حامدًا؛ حتى يجمع الأمرين.

وهو سبحانه يحمد نفسه بنفسه، ويحمد نفسه بما يُجريه على السنة الحامدين له من ملائكته وأنبيائه ورسله وعباده المؤمنين؛ فهو الحامد لنفسه بهذا وهذا. فإذا حمدهم له هُدِّيَتْه بهشته وأنسه وتكوينه؛ فإنه هو الذي ابتدأ النعم وولاها، فابتدأ الثناء وأنهى حمده، وهو الذي ألهم عبده التوبة وفرح بها أعظم فرح، وهي من فضله وجوده، وألهم عبده الطاعة وأعانه عليها فأناب عليه، وهي من فضله وجوده.

وهو سبحانه غني عن كل ما سواه بكل وجه، وما سواه فقير إليه بكل وجه، والعبد مفتقر إليه لذاته في الأسباب والغايات؛ فإن ما يكون به لا يكون، وما لا يكون لا ينفع. """,
  ),
  Fwaid(
    id: '111',
    name: """فصل """,
    text:
        """ وقوله ﷺ في الحديث: «إن الله جميل يحب الجمال»(١) يتناول جمال الثياب المسؤول عنه في نفس الحديث، ويدخل فيه بطريق العموم الجمال من كل شيء.

كما في الحديث الآخر: «إن الله نظيف يحب النظافة»(٢).

وفي الصحيح: «إن الله طيب لا يقبل إلا طيبًا»(٣).

وفي السنن: «الله يحب أن يرى أثر نعمته على عبده»(٤).

وفيها: عن أبي الأحوص الجشمي، عن أبيه، قال: رأى النبي ﷺ وعليَّ أطمارًا، فقال: «هل لك من مال؟» قلت: نعم. قال: «من أي المال؟» قلت: من كل ما آتى الله من الإبل والشاة. قال: «فلتر نعمة الله وكرامته عليك»(٥).

فهو سبحانه يحب أثر نعمته على عبده، فإنه من الجمال الذي يحبه، وذلك من شكره على نعمته، وهو جمال باطن؛ فيجب أن يُرى على العبد الجمال الظاهر بالنعمة، والجمال الباطن بالشكر عليه.

ومحبته سبحانه للجمال أنزل على عباده لباسًا وزينة تُجمل ظواهرهم وتقوى تجمل بواطنهم، فقال: ﴿يَا بَنِي آدَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَارِي سَوْآتِكُمْ وَرِيشًا وَلِبَاسُ التَّقْوَىٰ ذَٰلِكَ خَيْرٌ﴾ [الأعراف: ٢٦]، وقال في أهل الجنة: ﴿وَلَقَّاهُمْ نَضْرَةً وَسُرُورًا﴾ [الإنسان: ١١]، ﴿تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ﴾ [المطففين: ٢٤]، فجمل وجوههم بالنضرة وبواطنهم بالسرور.

وهو سبحانه يحب الجمال في الأقوال والأفعال والهيئة واللباس، ويبغض القبيح من الأقوال والأفعال والهيئة، فيبغض القبيح وأهله، ويحب الجمال وأهله.

ولكن ضل في هذا الموضع فريقان:

فريق قالوا: كل ما خلقه جميل؛ فهو يحب كل ما خلقه، ونحن نحب جميع ما خلقه، فلا نبغض منه شيئًا. ومن رأى الكائنات رأى كلها جميلة. وأسند مذهبهم: وإذا رأيت الكائنات بعينهم فجميع ما يحويه الوجود مليح، واحتجوا بقوله تعالى: ﴿الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ﴾ [السجدة: ٧]، وقوله: ﴿صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ﴾ [النمل: ٨٨]، وقوله: ﴿مَا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِن تَفَاوُتٍ﴾ [الملك: ٣]. والعارف عندهم هو الذي يفرح بإطلاق الجمال، ولا يرى في الوجود قبيحًا. وهؤلاء قد غابت البصيرة من قلوبهم عن التمييز والمعاداة في إنكار الكفر والمعاصي والجمال الذي أقامه الله في الوجود، ويرى جمال صفاته وأفعاله في الإحسان والعدل والرحمة، ويرى جمال صفاته في القهر والانتقام، ويرى جمال الذات في الأسماء الحسنى كلها. وربما غلا بعضهم حتى زعم أن معبوده يظهر في تلك الصورة ويدخل فيها، وإن كان اتحاديًا قال: هي مظهر من مظاهر الحق، ويسميها المظاهر الجمالية!!

والصواب: أن الله سبحانه جميل يحب الجمال، وهو يحب من عباده ما تجملوا به من طاعته، وما ظهر عليهم من أثر نعمته، ويبغض القبيح من الكفر والفسوق والعصيان، ويبغض أهله. فالجمال محبوب له لذاته، والقبيح مبغوض له لذاته، فالجمال المحبوب ما وافق أمره وشرعه، والقبيح المبغوض ما خالف أمره وشرعه.

والجمال نوعان: جمال ظاهر، وجمال باطن. فالجمال الظاهر هو حسن الصورة والهيئة واللباس، والجمال الباطن هو جمال القلب بالإيمان والإخلاص والمحبة والإنابة والتوكل والخشية والرجاء والحياء والصبر والشكر وسائر أخلاق الإيمان. وهذا هو الجمال الذي يحبه الله، وهو الذي يبقى مع العبد في دنياه وأخراه.

وأما جمال الصورة المجرد عن جمال الباطن، فقد يكون استدراجًا وفتنة، وقد يكون نعمة دنيوية لا تدل على كرامة، وقد يكون حجة على صاحبها. ولهذا كان النبي ﷺ يستعيذ بالله من شر فتنة الغنى، ومن شر فتنة الفقر.

فالله سبحانه يحب الجمال كله، ويبغض القبح كله، ولكن يحب جمال الطاعة ويبغض قبح المعصية، ويحب جمال الإيمان ويبغض قبح الكفر، ويحب جمال الصدق ويبغض قبح الكذب، ويحب جمال العدل ويبغض قبح الظلم.

فمن أحب الجمال الذي يحبه الله، وبغض القبح الذي يبغضه الله، فقد وافق الله في محبته وبغضه، ومن أحب الجمال الذي يبغضه الله، أو أبغض الجمال الذي يحبه الله، فقد خالف الله في محبته وبغضه.

وبالله التوفيق.""",
  ),
  Fwaid(
    id: '112',
    name: """فصل """,
    text:
        """وقابلهم الفريق الثاني، فقالوا: قد ذم سبحانه جمال الصور وتمام القامة والخلقة، فقال عن المنافقين:
﴿وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ﴾ [المنافقون/٤]، وقال:
﴿وَإِن يَقُولُوا تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ﴾ [المنافقون/٤]،
وقال: ﴿لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾ [التين/٤]، أي أمواهًا.
وقال الحسن: الصور. وفي صحيح مسلم عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله ﷺ: «إن الله لا ينظر إلى صوركم ولا إلى أجسامكم»، قالوا: «ولا إلى قلوبكم وأعمالكم؟» قالوا: قالوا: «بلى»، قالوا: «فقد حرم علينا لبس الحرير والذهب والفضة»، وقال: ﴿وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ زَهْرَةَ الْحَيَاةِ الدُّنْيَا﴾ [طه/١٣١]، وذلك من أعظم جمال الدنيا. وفي الحديث: «إن الله يحب الإحسان»، وقد ذم الله المسرفين، والسرف يكون في الطعام والشراب كما يكون في اللباس.

وفصل النزاع أن يقال: الجمال في الصورة واللباس والهيئة ثلاثة أنواع:
ما يُحمد، ومنه ما يُذم، ومنه ما لا يتعلق به مدح ولا ذم؛
فالمحمود منه ما كان لله وأعان على طاعة الله وتنفيذ أوامره والاستجابة له، كما كان النبي ﷺ يتجمل للوفود، وهو نظير لباس الحرب للقتال، ولباس الحرير في الحرب والخيلاء فيه، فإن ذلك محمود إذا تضمن إعلاء كلمة الله ونصر دينه وغيظ عدوه.
والمذموم منه ما كان للدنيا والرئاسة والفخر والخيلاء والتوسل إلى الشهوات، وأن يكون هو غاية العبد وأقصى مطلبه، فإن كثيرًا من النفوس ليس لها همة سوى ذلك.
وأما ما لا يُحمد ولا يُذم فهو ما خلا عن هذين القصدين وتجرد عن الوصفين.

والمقصود من هذا الحديث الشريف مشتمل على أصلين عظيمين:
أحدهما: معرفة، وآخره سلوك؛ فيُعرِّف الله سبحانه بالجمال الذي لا يماثله فيه شيء، ويتحبب بالجمال الذي يحبه من الأقوال والأعمال والأخلاق؛ فيجب على عبده أن يتجمل باللسان بالصدق، وبالقلب بالإخلاص والمحبة والإنابة والتوكل، وبالجوارح بالطاعة، وبدنه بإظهار نعمته عليه وشكره له، وتطهيره له من الأنجاس والأحداث والأوساخ والشعور المكروهة والخُبثان وتقديم الأظفار؛ فيعرفه بصفات الجمال ويتعرف إليه بالأفعال والأقوال والأخلاق الجميلة؛ فيعرفه بالجمال الذي هو وصفه، ويعبده بالجمال الذي هو شرعه ودينه؛ فيجمع الحديث قاعدتين: المعرفة والسلوك. """,
  ),
  Fwaid(
    id: '113',
    name: """فصل """,
    text:
        """ ليس للعبد شيء أنفع من صدقه ربه في جميع أموره مع صدق العزيمة، فيصدقه في عزمه. [١٥] قال تعالى: ﴿فَإِذَا صَدَقَ الْأَمْرُ﴾ [محمد/٢١]، فسعادة صدق العزيمة وصدق الفعل. صدق العزيمة جمعها وحزمها وعدم التردد فيها.

٢٧١

بل تكون عزيمته لا يشوبها تردد ولا تلوّن، فإذا صدقت عزيمته بقي عليه صدق الفعل، وهو استفراغ الوسع وبذل الجهد فيه، وأن لا يتخلف عنه بشيء من ظاهره وباطنه. فغريبة القصد تمنعه من ضعف الإرادة والهمة، وصدق الفعل يمنعه من الكسل والفتور.

ومن صدق الله في جميع أموره صنع الله فوق ما يصنع لغيره.

وهذا الصدق معنى يلتئم من صحة الإخلاص وصدق التوكل، فأصلهما الناس من صح إخلاصه وتوكله.""",
  ),
  Fwaid(
    id: '114',
    name: """ فائدة جليلة في القدر""",
    text: """ربُّ ذو إرادةٍ أراد من عبده ذا إرادةٍ:

فإن وافق إرادته من نفسه التي عيَّنه وألهمه فعل ما أُمِر به،
وإن خذله خلاه وإرادته ونفسه، وهو من هذه الحيثية لا يُجبر إلا ما تهواه نفسه وطبعُه، فهو من حيث هو إنسان لا يريد إلا ذلك، ولذلك ذمَّه الله في كتابه من هذه الحيثية، ولم يمدحه الأمر زائداً على تلك الحيثية، وهو كونه مسلماً ومؤمناً وصابراً ومُحسناً وشكوراً وتقياً ونحو ذلك.

وهذا أمرٌ زائد على مجرد كونه إنساناً وإرادته صالحة، لكن لا يكفي مجرد صلاحها لأن لم يكن له قدر زائد على ذلك، وهو التوفيق، كما أنه لا يكفي مجرد الرؤية الصحيحة للإدراك لم تحصل للإدراك آخر من النور المنفصل عنها. """,
  ),
  Fwaid(
    id: '115',
    name: """فصل """,
    text:
        """ من أعظم الظلم والجهل أن تطلب التعظيم والتوقير لك من الناس وتلك إلى من تعظيمه وتوقيره، فبقدر توقيرك للمخلوقين يجب أن يراك.

في حال لا شيء إلا أن الله إلى علمها!

قال تعالى: ﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنْفُسِهِمْ﴾ [الرعد/١١].

وهذه الأقوال ترجع إلى معنى واحد، وهو أنهم لم يعظموا الله، وعرفوا عظمته، وقدره، وأمروه بطاعته سبحانه واجتناب معاصيه، وإجلاله، والحياء منه، ومهابته في القلوب.

ولهذا قال بعض السلف: ليعظم قدر الله في قلبك قبل أن يذكرك عند عبد؛ فإن استحييت من مخلوق ولم تستحي من الله، كما قالوا: تستحي من الكلب والغرور ولا تستحي من الله؟!

ومن وقار الله أن لا تعتدي على خلقه، لا في اللفظ بحيث تقول: والله وجاهك يا فلان، أو أنت وما شاء الله، أو لا تحب الخلق كما تحب الله، أو تقول: لولا فلان ما كان كذا، أو ما شاء الله وشئت، ولا في العمل بحيث تطيع المخلوق في معصية الخالق، أو تجعل له نذراً أو قرباناً، أو ترضى أن يُذكر دون الله، أو تُعظِّمه بما لا ينبغي إلا لله.

ولا يكون العبد لله ولياً حتى يكون لله عبداً، ولا يكون لله عبداً حتى يكون لله خالصاً، ولا يكون لله خالصاً حتى يكون لله محباً، ولا يكون لله محباً حتى يكون لله خائفاً راجياً.

ومن وقار الله أن يستحيي من اطلاع الله على سريرته وضميره فيرى فيه ما يكرهه.

ومن وقار الله أن يستحيي منه في الخلوة [١٩٦] أعظم مما يستحي من أكابر الناس.

والمقصود أن لا يوقر الله وكلامه وما آتاه من العلم والحكمة كيف يطلب من الناس توقيره وتعظيمه؟!

والقرآن والعلم وكلام الرسول ﷺ صلات من الحق وتنبيهات ورداع وزواجر وإرادة إليك، والشبه زاجر ورداع وموقظ قائم بك، فلا ما ورد إليك وعظك، ولا ما قام بك نصحك، ومع هذا تطلب هذا التعظيم والتوقير؟! فأنت كصاب لم تؤثر فيه مصيبة وعقلاً واعتباراً، وهو يطلب من غيره أن يحفظ وينزجر بالنظر إلى مصيبته؛ فلم يؤثر فيه زجر، وهو يريد الانزجار من نظره إلى ضربه؟!

من سمع بالمكائد والعقوبات والآيات في حق غيره ليس كمن رآها عياناً في نفسه؛ فكيف من وحده؟! نفسه، فإن الآفاق مشهودة معلومة، والآيات في النفس مشهودة مرئية؛ فعياذاً بالله من الخذلان.

قال تعالى: ﴿إِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ * وَلَوْ جَاءَتْهُمْ كُلُّ آيَةٍ حَتَّى يَرَوُا الْعَذَابَ الْأَلِيمَ﴾ [يونس/٩٦-٩٧].

وقال: ﴿وَلَوْ أَنَّا نَزَّلْنَا إِلَيْهِمُ الْمَلَائِكَةَ وَكَلَّمَهُمُ الْمَوْتَى وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَيْءٍ قُبُلًا مَا كَانُوا لِيُؤْمِنُوا إِلَّا أَنْ يَشَاءَ اللَّهُ﴾ [الأنعام/١١١].

والعاقل المزود بالتوفيق يعتبر بدون هذا ويُتِمُّ ناقص خِلْقته بفضائل أخلاقه وأعماله، فكلما امتلأ من جثمانه ازداد في إيمانه أثراً، وكلما نقص من قوى بدنه زاد في قوة إيمانه ويقينه ورغبته في الله والدار الآخرة.

وإن لم يكن هذا فالموت خير له؛ لأنه لا يقف به على حد معين من الألم والفساد، بخلاف العيوب والنقائص في طول العمر؛ فإنها زيادة في الهدم وهدم الحسنة، وإنما حسن طول العمر ونفعه لحصول الذكر والاستدراك وإعظام الأجر والوزر والتصحيح كما قال تعالى: ﴿وَالَّذِينَ يُؤْتَوْنَ مَا آتَوْا وَقُلُوبُهُمْ وَجِلَةٌ﴾ [المؤمنون/٦٠].

فمن لم يؤثر به التعمير وطول البقاء إصلاح معايبه وتدارك فارطه وإغاثة نفسه، فأعمال حياته كجناح سفر العبد على جناح سفر إما إلى الجنة وإما إلى النار؛ فإذا طال عمره وحسن عمله كان طول سفره زيادة في حصول النعيم واللذة؛ فإن كلما طال السفر إليها كانت الصبابة أجل وأفضل، وإذا طال عمره وساء عمله كان طول سفره زيادة في الألم وعذابه ونزوله إلى أسفل؛ فالمسافة إما صاعدة وإما نازلة.

وفي الحديث المرفوع: «خيركم من طال عمره وحسن عمله»(١).

والطالب الصادق في طلبه كلما أخرجه شيء من ذاته جعله عمارة لقلبه وروحه، وكلما منعه شيء من دنياه جعله زيادة في آخرته، وكلما منع شيئاً من متاع دنياه جعله زيادة في ذاته، وكلما أصابه حزن أو هم جعله في أفراح آخرته، فنقصان بدنه ودنياه ولذته وجاهه ورئاسته إن زاد في حصول ذلك وتوفيره عليه في معاده كان رحمة له وخيراً، وإلا كان حرماناً وعقوبة على ذنب ظاهراً أو باطناً؛ فإن حرمان خير الدنيا والآخرة مرتب على هذه الأربعة.

وبالله التوفيق.""",
  ),
  Fwaid(
    id: '116',
    name: """ فائدة""",
    text:
        """ الناس منذ خُلِقوا لم يزلوا مسافرين، وليس لهم حطٌّ عن رحالهم إلا في الجنة أو النار.

والعاقل يعلم أن السفر مبنيٌّ على المشقّة وركوب الأخطار، ومن المحال عادةً أن يطلب فيه نعيمٌ ولذّةٌ وراحةٌ، إنما ذلك بعد انتهاء السفر.

ومن المعلوم أن كل وطأةٍ قدَمٍ أو كل آنَةٍ من آنات السفر غيرُ واقفةٍ، ولا المسافر واقفٌ، وقد ثبت أنه مسافرٌ على الحال التي يجب أن يكون المسافر عليها من تهيئة الزاد الموصل، فإذا نزل أو نام أو استراح فعلى قدم الاستعداد للسير.""",
  ),
  Fwaid(
    id: '117',
    name: """ فائدة""",
    text:
        """ عند العارفين أن الاشتغال بالمشاهدة عن الزهد في السير وقوفٌ؛ لأنه في زمن المشاهدة لو كان صاحب عملٍ ظاهرٍ أو باطنٍ أو ازديادٍ من معرفةٍ وإيمانٍ مُفصِلٍ أولى به، فإن اللطيفة الإنسانية على صورة عملها ومعرفتها وهمّتها وإرادتها، والبدن يحضر على صورة عمله الحسن أو القبيح، وإذا انتقلت من هذه الدار شاهدت حقيقة ذلك.

وعلى قدر قرب قلبك من الله تبعد من الأنس بالناس ومساكنتهم، وعلى قدر صيانة سرك وإرادتك يكون حفظه، وملاك ذلك صحة التوحيد، ثم صحة العلم بالطريق، ثم صحة الإرادة، ثم صحة العمل.

والحذر الحذر كل الحذر من قصد الناس لك وإقبالهم عليك وأن يغتروا على موضع عرضك؛ فإنها الآفة العظمى.""",
  ),
  Fwaid(
    id: '118',
    name: """ فصل""",
    text: """ كل ذي لب يعلم أنه لا طريق للشيطان عليه إلا من ثلاث جهات:

إحداها: التزيد والإسراف، فيزيد على قدر الحاجة، فنصير فضلة، وهي حظ الشيطان ومدخله إلى القلب. وطريق الاحتراز [منه] الاحتراز من إعطاء النفس تمام مطلوبها من غذاء أو نوم أو لذّة أو راحة؛ فمتى أغلقت هذا الباب حصل الأمان من دخول العدو منه.

الثانية: الغفلة؛ فإن الذاكر في حصن الذكر، فمتى غفل فتح باب الحصن، فولج العدو، فيُعسِر عليه ويصعب إخراجه.

الثالثة: تكلّف ما لا يعنيه من جميع الأشياء.""",
  ),
  Fwaid(
    id: '119',
    name: """فائدة """,
    text:
        """ طالب النفوذ إلى الله والدار الآخرة – بل وإلى كل علم وصناعة ورئاسة – بحيث يكون راسخًا في ذلك مقتديًا به فيه، يحتاج أن يكون شجاعًا، مقدامًا، حاكمًا على وهمه، غير مَهزومٍ تحت سلطان تخيّله، زاهدًا في كل ما سوى مطلوبه، عالقًا لما توجه إليه، عارفًا بطريق الوصول إليه والطرق القواطع عنه، مقدام الهمة، ثابت الجأش، غير مائل عن مطلوبه لذبح نفسه ولا على ذبح اللحم، قانعًا بما يحتاج إليه من أسباب معونة، لا تستفزه المعارضات، شعارُه الصبر، وراحته التعب، محبًّا لمكارم الأخلاق، حافظًا لوقته، لا يخالط الناس إلا على حذرٍ كالطائر الذي يلتقط الحب بينهم، قانعًا على نفسه بالرغبة والهمة، غير مسيء من حواسه شيئًا، ولا مصرِفًا لخواطره في غير ما هو بصدده، وملاك ذلك هجر العوائد وقطع العلائق الخلائق بينك وبين المطلوب.""",
  ),
  Fwaid(
    id: '120',
    name: """ فائدة""",
    text:
        """ من الذاكرين من يبتدئ بذكر اللسان، وإن كان على غفلة، ثم لا يزال فيه حتى يحضر قلبه، فيواطئان على الذكر. ومنهم من لا يرى ذلك، ولا يبتدئ على غفلة، بل يسكن حتى يحضر قلبه، فيشرع في الذكر بقلبه، فإذا قوي استتبع لسانه، فواطئا جميعا.

٢٧٨

فالأول ينتقل الذكر من لسانه إلى قلبه.

والثاني ينتقل من قلبه إلى لسانه، من غير أن يخلو قلبه منه، بل يسكن أولاً حتى يحس بظهور اللسان فيه، فإذا أحس بذلك نطق قلبه، ثم انتقل من الذكر القلبي إلى الذكر اللساني، ثم يستقران في ذلك حتى يجد كل شيء منه ذاكرا.

وأفضل الذكر وأنفعه ما واطأ فيه القلب اللسان، وكان من الأذكار النبوية، وشهد الذاكر معانيه ومقاصده.""",
  ),
  Fwaid(
    id: '121',
    name: """ فصل""",
    text:
        """أنفع الناس لك رجل مكنك من نفسه حتى تزرع فيه خيرًا أو تصنع إليه معروفًا؛ فإنه نعم العون لك على منفعتك وكمالك؛ فتعاملك به في الحقيقة مثل انتفاعك بأبٍ أو أكثر.

وأضر الناس عليك من مكن نفسه منك حتى تعصي الله فيه؛ فإنه عونك لك على خسارتك ونقصك. """,
  ),
  Fwaid(
    id: '122',
    name: """ فصل""",
    text:
        """اللذة المحرمة ممزوجة بالقبح حال تناولها، ثمرتها الألم بعد انقضائها؛ فإذا [١٩٧] اشتدت الداعية منك إليها ففكّر في انقطاعها وبقاء تبعتها وألمها، ثم وازن بين الأمرين، وانظر ما بينهما من التفاوت.

والتعب بالطاعة ممزوج بالحسن، مثمر للذة والراحة؛ فإذا ثقلت على النفس ففكّر في انقطاع تعبها وبقاء حسنها ولذتها وسرورها، ووازن بين الأمرين، وآثر الراجح على المرجوح.

فإن تألّمت باللبس فانظر إلى ما في المآل من الفرحة والسرور واللذة، وإن تألّمت بالمقاساة فانظر إلى ألم ترك اللذة المحرمة، ووازن بين الأمرين.

وخاصة العقل تحصيل أعظم المنفعتين بتفويت أدناهما، واحتمال أصغر الألمين لدفع أعظمهما.

وهذا يحتاج إلى علم بالأسباب ومقتضياتها، وإلى عقل يختار الأولى والأنفع له منها؛ فمن وُفِّق قسمة من العقل والعلم اختار الأفضل وآثره، ومن نقص حظه منهما أو من أحدهما اختار خلافه، ومن فكّر في الدنيا والآخرة علم أنه لا ينال واحدًا منهما إلا بمشقّة؛ فيتحمّل المشقّة لأخراهما وأبقاهما. """,
  ),
  Fwaid(
    id: '123',
    name: """ فصل""",
    text:
        """الله على العبد في كل عضو من أعضائه أمر، وله عليه فيه نهي، وله فيه نعمة، وله فيه منفعة ولذة؛ فإن قام لله في ذلك العضو بأمره، واجتنب فيه نهيه أدّى شكر نعمته عليه فيه، وسعى في تكميل انتفاعه ولذته به، وإن عطّل أمر الله فيه عطّلته عنه من انتفاعه بذلك العضو، وجعله من أكبر أسباب ألمه ومضرته.

وله عليه في كل وقت من أوقاته عبودية يتقدم إليه وتقرّبه منه، فإن شغل وقته بعبودية الوقت تقدّم إليه ربه، وإن شغله بهوى أو راحة وبطالة تأخّر.

فالعبد لا يزال إما متقدّمًا أو متأخرًا، ولا وقوف في الطريق ألبتة.

قال تعالى: ﴿لِمَن شَاءَ مِنكُمْ أَنْ يَتَقَدَّمَ أَوْ يَتَأَخَّرَ﴾ [المدثر/ ٣٧]. """,
  ),
  Fwaid(
    id: '124',
    name: """فصل """,
    text: """ أقام الله سبحانه هذا الخلق بين الأمر والنهي والعطاء والمنع؛
فانقسموا فريقين:

فرقة قابلت أمره بالترك، ونهيه بالارتكاب، وعطاءه بالغفلة عن الشكر، ومنعه بالسخط. وهؤلاء أعداؤه، وفيهم من العداوة بحسب ما فيهم من ذلك.

وقسم قالوا: إنما نحن عبيدك؛ فإن أمرتنا سارعنا إلى الإجابة، وإن نهيتنا أمسكنا نفوسنا وكففناها عما نهيتنا عنه، وإن أعطيتنا حمدناك، وإن منعتنا تضرعنا إليك وذكرناك.

فليس بين هؤلاء وبين الجنة إلا ستر الحياة الدنيا؛ فإذا مزقه عليهم الموت صاروا إلى النعيم المقيم وقرة الأعين، كما كان أولئك ليس بينهم وبين النار إلا ستر الحياة؛ فإذا مزقه الموت صاروا إلى الحسرة والألم.

فإذا تصادمت في قلبك جنود الدنيا والآخرة، وأردت أن تعلم أي الفريقين أقرب إليك، فانظر مع من تميل منهما، ومع من تقاتل؛ إذ لا يمكنك الوقوف بين الجبهتين، فأنت مع أحدهما لا محالة.

فانظرين أحد الفريقين: هل استمسكوا الهوى خالقهم، واستصحبوا العقل فشاوروهم، وزيّنوا قلوبهم للفكر فيما خلقوا له، وجوارحهم للعمل بما أمروا به، وأوقاتهم لمعمارها بعمر الآخرة، واستظهروا على سرعة الأجل بالمبادرة إلى الأعمال، وسكنوا الدنيا وقلوبهم مسافرة عنها، واستوطنوا الآخرة قبل انتقالهم إليها، وآمنوا بالله وطاعته على قدر حاجتهم إليه، وزوّدوا للآخرة على قدر مقامهم فيها؛ فغسل لهم سبحانه من نعيم الجنة وروحها أن أنسهم بنفسه، وأقبل بقلوبهم إليه، وجمعها على محبته، وشوقهم إلى لقائه، ونعّمهم بقربه، وفرغ قلوبهم مما ملأ قلوب غيرهم من محبة الدنيا والهم والحزن على فواتها والنقم خوف ذهابها، فاستراحوا لما استراحوا المتزوّدون، وأنسوا بما استوحش من الجاهلون، فحقروا الدنيا بأعيانهم، والمُلك الأعلى بأرواحهم.""",
  ),
  Fwaid(
    id: '125',
    name: """فصل """,
    text:
        """التوحيد ألطف شيء وأزهره وأنظفه وأصفاه، فأدنى شيء يخدشه ويكدّره ويؤثر فيه؛ فهو كأبيض ثوب يكون يؤثر فيه أدنى أثر، وكالمرآة الصافية جداً أدنى شيء يؤثر فيها. ولهذا تستوشِه اللمحة واللفظة والشهوة الخفية؛ فإن بادر سحبه وقلع ذلك الأثر بفساده، وإلا استحكم وصار طبعاً يتعسر عليه قلعه.

وهذه الآثار والطبائع التي تحصل فيه: منها ما يكون سريع الحصول سريع الزوال، ومنها ما يكون سريع الحصول بطيء الزوال، ومنها ما يكون بطيء الحصول سريع الزوال، ومنها ما يكون بطيء الحصول بطيء الزوال.

ولكن من الناس من يكون توحيده كبيراً عظيماً، فينغمر فيه كثير من تلك الآثار ويستحيل فيه، بمنزلة الماء الكثير الذي يخالطه أدنى نجاسة أو وسخ؛ فيستهلكه، بعكس صاحب التوحيد الذي هو دونه، فيخالطه من النجس الضعيف ما يخالط به صاحب التوحيد العظيم الكثير توحيده، فيظهر أثره ما لم يظهر في التوحيد الكثير.

وأيضاً فإن المحل الصافي جداً يظهر لصاحبه ما لا يظهر في المحل الذي لم يبلغ في الصفاء مبلغه؛ فيدركه بالإزالة دون هذا، فإنه لا يشعر به.

وأيضاً فإن قوة الإيمان والتوحيد إذا كانت قوية جداً أحلت المواد الرديئة وغيّرتها، بخلاف القوة الضعيفة.

وأيضاً فإن صاحب المحاسن الكثيرة والمغفرة للسيئات يُسامَح بما لا يُسامَح به من أتى مثل تلك السيئات وليس له مثل تلك المحاسن، كما قيل:

وإذا الحبيب أتى بذنب واحد
جاءت محاسنه بألف شفيع

وأيضاً فإن صدق الطلب وقوة الإرادة وكمال الاعتقاد يُزيل تلك العوارض والأوساخ العارضة إلى مقتضاها ووجهها، بخلاف الكذب وفساد القصد وضعف الاعتقاد؛ فيجعل الأعمال الممدوحة لوجه الله وجهه، ويُفسد ذلك في الأخلاط الغالبة والحاملة لصالح الأغذية إلى طبعها. """,
  ),
  Fwaid(
    id: '126',
    name: """فائدة """,
    text:
        """ ترك الشهوات لله وإن أنجى من عذاب الله وأوجب الفوز برحمته؟ ففاحذر الله وكنز البر ولذة الأنس والشوق إليه والفرح والابتهاج به لا تحصل في قلب فيه غيره ممن كان من أهل العبادة والزهد والعلم؛ فإن الله سبحانه إنما جعل الخير كله في قلب من سواه، وإنما يروع ذكراه في قلب ليس فيه غيره، والفقر غناه بالله، والعز ذله دونه، والنعم عذاباً دونه، والعذاب نعيمًا معه.

ــــــــــــــــــــــ
(١) البيت بلا نسبة في فتح الطيب (٢/٥).

٢٨٣

وبالجملة فلا يرى الحياة إلا به ومعه، والموت والألم والهم والحزن إذا لم يكن معه، فهذا دار حزن في الدنيا سعادة، وجنة يوم القيامة.""",
  ),
  Fwaid(
    id: '127',
    name: """ فائدة""",
    text:
        """ الإنابة هي عكوف القلب على الله عز وجل كعكوف البدن في المسجد لا يفارقه.

وحقيقة ذلك عكوف القلب على محبته، وذكره بالإجلال والتعظيم، وعكوف الجوارح على طاعته بالإخلاص له والمتابعة لرسوله.

ومن يتعكف قلبه على الله وحده عكف على التماثيل المتنوعة، كما قال إمام الحنفاء لقومه: ﴿مَا هَذِهِ التَّمَاثِيلُ الَّتِي أَنتُمْ لَهَا عَاكِفُونَ﴾ [الأنبياء/٥٢].

فانقسموا هو وقومه حقيقة العكوف؛ فكان حظ قومه العكوف على التماثيل، وكان حظه العكوف على الرب الجليل. والتماثيل جمع تمثال وهي الصور الممثلة.

تعلق القلب بغير الله واشتغاله والركون إليه عكوف منه على التماثيل التي قامت بقلبه، وهو نظير العكوف على تماثيل الأصنام؛ ولهذا كان شرك عباد الأصنام بالعكوف بقلوبهم وهممهم وإراداتهم على تماثيلهم.

فإذا كان في القلب تماثيل قد ملكته واستعبدته بحيث يكون عاكفًا عليها؛ فهو نظير عكوف عباد الأصنام عليها، ولهذا سماه النبي ﷺ عبدًا لها ودعا عليه بالنكس، فقال: «تعس عبد الدينار، تعس عبد الدرهم، تعس وانتكس، وإذا شيك فلا انتقش».

الناس في هذه الدار [١٩٨] على جناح سفر كلهم، وكل مسافر فهو ظاعن إلى مقصده ونازل على من يشير النزول عليه، وطالب الله والدار الآخرة إنما هو ظاعن إلى الله في حال سفره ونازل عليه عند القدوم عليه؛ فهذه نهاية سفره ومنتهى قضيته.

﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ۝ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً ۝ فَادْخُلِي فِي عِبَادِي ۝ وَادْخُلِي جَنَّتِي﴾ [الفجر/٢٧-٣٠].

وقالت امرأة فرعون: ﴿رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ﴾ [التحريم/١١]، فطلبت كون البيت عنده قبل طلبها أن يكون في الجنة؛ فإن الجار قبل الدار.

من كلام الشيخ علي

قيل له في نوم يقظة أو يقظة كالنوم:

لا تبد نافقة إلى غيري فاضعفها عليك، مكافأة لخروجك عن حدك في عبوديتك.

ابتليتك بالفقر لتصير ذهبًا خالصًا؛ فلا ترقين بعد السبك.

حكمت لك بالفقر ولنفسك بالغنى؛ فإن وصلتها بي وصلتك.

(١) أخرجه البخاري (٢٨٨٧، ٢٨٨٨) عن أبي هريرة.
(٢) لم أعرف من هو.

٢٨٥

بالغنى، وإن وصلتها بغيري حسدت عندك موارد معنويتي طردًا لك عن بادي.

لا تركن إلى شيء دوني؛ فإنه وبال عليك، وقاتل لك؛ إن كنت لا العمل ركنت عليه، وإن ركنت إلى المعرفة شكّرت عليها، وإن ركنت إلى الوجد أحبطته، وإن ركنت إلى العلم نقضته، وإن ركنت إلى المخلوقين وكذلك إليهم، أرضناك ربنا رضاك لنا عبدًا.""",
  ),
  Fwaid(
    id: '128',
    name: """فائدة """,
    text: """ البهجة التي تعرض عند سماع القرآن إن لم غيرها لها أسباب:

أحدها: أن يلوح له عند السماع درجة ليست له، فيفرح بها، فتحدث له هذه البهجة شهوة شوق.

وثانيها: أن يلوح له ذنب ارتكبه، فيهشّ حقًا وحزنًا على نفسه، وهذه بهجة خشية.

وثالثها: أن يلوح له نقص فيه لا يقدر على دفعه عنه، فيحدث له ذلك حزنًا، فهي بهجة حزن.

ورابعها: أن يلوح له كمال محبوبه، ويرى الطريق إليه مسدودة عنه، فيحدث له ذلك شهوة أسف وحزن.

وخامسها: أن يلوح له كمال محبوبه، فيرى الطريق مفتوحًا ظاهرة، فيحدث له ذلك فرحًا وسرورًا بما لاح له.

وكل حال فسبب الشهوة قوة الوارد وضعف المحل عن الاحتمال.

والقوة أن يعمل ذلك الوارد عمله داخلًا ولا يظهر عليه، وذلك أقوى وأدوم؛ فإنه إذا ظهر ضعف أثره وأوشك انقطاعه.

هذا حكم الشهوة من الصادق؛ فإن الشاهد إما صادق وإما سارق وإما منافق.""",
  ),
  Fwaid(
    id: '129',
    name: """ قاعدة نافعة""",
    text:
        """أصل الخير والشر من قبل التفكير؛ فإن الفكر مبدأ الإرادة والطلب والزهد والترك والحب والبغض.

وأنفع الفكر الفكر في مصالح المعاد وفي طرق اجتلابها، وفي دفع مفاسد المعاد وفي طرق دفعها، وأفكار الدنيا هي في الآخرة وبها أربعة: الفكر في مصالح المعاد وطرق تحصيلها، وتفكير مصالح الدنيا وطرق الاحتراز منها. فهذه الأقسام الثمانية دارت أفكار العقلاء.

ورأس القسم الأول: الفكر في آلاء الله ونعمته، وأمره ونهيه، وطرق العلم به وبأسمائه وصفاته من كتابه وسنة نبيه وما والاهما. وهذا الفكر يثمر لصاحبه المحبة والمعرفة؛ فإذا زاد في الآخرة وشرفها ودوامها وفي الدنيا وضعتها وفناءها؛ أوجب له ذلك الرغبة في الآخرة والزهد في الدنيا. وكلما زاد في فهم الأوامر والنواهي أورثه ذلك الحرص والاجتهاد وبذل الوسع في امتثال الأوامر واجتناب النواهي؛ وهذه الأفكار أعلى همه، وتجمعها موتها وسرورها، وتجعلها واد والناس في واد.

وبإزاء هذه الأفكار الأفكار الرديئة التي تجول في قلوب أكثر هذا الخلق:

فالفكر فيما لم يكلف الفكر فيه ولا أعطي الإحاطة به من فضول العلم الذي لا ينفع؛ كالفكر في كيفية ذات الرب وصفاته مما لا سبيل للعقول إلى إدراكه.

ومنها: الفكر في الصناعات الدقيقة التي لا تنفع بل تضر؛ كالفكر في الشطرنج والموسيقى وأنواع الأشكال والتصاوير.

ومنها: الفكر في العلوم التي لو كانت صحيحة لم يحط الفكر فيها للنفس كمالا ولا شرفا؛ كالفكر في دقائق المنطق والعلم الرياضي والطبيعي وأكثر علوم الفلاسفة، التي لو بلغ الإنسان غايتها لم يكمل بذلك ولم يزك نفسه.

ومنها: الفكر في الشهوات واللذات وطرق تحصيلها، وهذا وإن كان للنفس فيه لذة لكن لا عاقبة له، ومضرته في عاقبة الدنيا قبل الآخرة أضعاف مسرته.

ومنها: الفكر فيما لم يكن أو كان كيف يكون؛ كالفكر فيما إذا صار ملكا، أو وجد كنزا، أو ملك ضيعة؛ كيف يصنع؟ وكيف يتصرف ويأخذ ويعطي ويقسم؟ وذلك كله من أضغاث الحلم.

ومنها: الفكر في جزئيات أحوال الناس وماجرياتهم ومداخلهم ومخارجهم وتوابع ذلك من فكر النفوس المبطلة الفارغة من الله ورسوله والدار الآخرة.

ومنها: الفكر في دقائق الحيل والمكر التي يتوصل بها إلى أغراضه وهواه، مباحة كانت أو محرمة.

ومنها: الفكر في أنواع الشعر وصرفه وأغانيه في المدح والهجاء والغزل والمرازي ونحوها؛ فإنه يشغل الإنسان عن الفكر فيما فيه سعادته وحياته الدائمة.

ومنها: الفكر في المقدررات الذهنية التي لا وجود لها في الخارج ولا بالناس حاجة إليها، وذلك موجود في كل علم، حتى في علم الفقه والأصول والطب.

فكل هذه الأفكار مضرها أرجح من منفعتها، ويكفي في مضرتها شغلها عن الفكر فيما هو أولى به وأعود عليه بالنفع عاجلا وآجلا. """,
  ),
  Fwaid(
    id: '130',
    name: """فصل """,
    text: """ الطلب لقاح الإيمان؛ فإذا اجتمع الإيمان والطلب أثمرا العمل الصالح.

وحسن الظن بالله لقاح الافتقار والاضطرار إليه؛ فإذا اجتمعا أثمرا إجابة الدعاء.

والخشية لقاح المحبة؛ فإذا اجتمعا أثمرا امتثال الأوامر واجتناب المناهي.

والصبر لقاح اليقين؛ فإذا اجتمعا أورثا الإمامة في الدين، قال تعالى: ﴿وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ﴾ السجدة (٢٤).

وصحة الاقتداء بالرسول لقاح الإخلاص؛ فإذا اجتمعا أثمرا قبول العمل والاعتداد به.

والعمل لقاح العلم؛ فإذا اجتمعا كان الفلاح والسعادة، وإن انفرد أحدهما عن الآخر لم يفد شيئا.

والعلم لقاح العلم؛ فإذا اجتمعا حصلت سيادة الدنيا والآخرة وحصل الانتفاع بالعلم، وإن انفرد أحدهما عن صاحبه فات النفع والانتفاع.

والخبرة لقاح البصيرة؛ فإذا اجتمعا نال صاحبهما خير الدنيا والآخرة، وإن انفرد أحدهما عن الآخر كان كالمختلف الكلمات إما من عدم الخبرة وإما من عدم البصيرة.

وحسن القصد لقاح صحة الذهن؛ فإذا فقد أحدهما فسد الفكر كله، وإذا اجتمعا أنتج أنواع الخيرات.

وصحة العزيمة لقاح الشجاعة؛ فإذا اجتمعا كان النصر والظفر، وإن فقد أحدهما خذلان والخيبة، وإن وجد الرأي بلا شجاعة فالنصر بعيد، وإن حصلت الشجاعة بلا رأي فالتهور والعطب.

والصبر لقاح الرأي؛ فإذا اجتمعا حسنا، قال الحسن: ما قرن إلى رأي صبر إلا حسن رأيه، وما قرن إلى رأي صبر إلا أرى صاحبه بصيرا، وإذا ارتبط صبرا بصيرا فذلك.

والتثبت لقاح العقل؛ فكلاهما يقرب بالصحيح من القول والفعل.

والزهد لقاح الفكر كما أن الطمع لقاح الأشر؛ فإذا اجتمعا انقلب الزهد في الدنيا والرغبة فيما عند الله.

والقوة لقاح التوكل؛ فإذا اجتمعا استقام القلب.

ولقاح أخذ الأمر لقاح الاستعداد للقاء؛ فبقدر الأمل يكون الاستعداد.

٢٩٠

كله في اجتماعهما، والنقص في فرقتهما.

ولقاح الهمة العالية النية الصحيحة؛ فإذا اجتمعا بلغ العبد غاية همه المراد.*""",
  ),
  Fwaid(
    id: '131',
    name: """قاعدة """,
    text:
        """ للعبد بين يدي الله موقفان: موقف بين يديه في الصلاة، وموقف بين يديه يوم لقائه؛ فمن قام بحق الموقف الأول هان عليه الموقف الآخر، ومن استهان بهذا الموقف ولم يقم بحقه شدد عليه ذلك الموقف. قال تعالى: ﴿وَمَنْ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا﴾ [الإسراء: ١٩].""",
  ),
  Fwaid(
    id: '132',
    name: """قاعدة """,
    text:
        """ اللذة من حيث هي مطلوبة للإنسان بل ولكل حي؛ فلا تذم من جهة كونها لذة، وإنما تذم ويكون تركها خيرا من نيلها وأنفع إذا تضمنت لذات لم تضم منها، أو أكمل، أو أعقب تحصيلها ألما أعظم من ألم فواتها، وهذا ظاهر في العقل الفاضل الفطن، والأحمق من لم يعرف العقل التفاوت بين اللذتين والألمين، وأنه لا نسبة لإحداهما إلى الأخرى، هان عليه ترك أدنى اللذتين لتحصيل أعلاهما، واحتمال أيسر الألمين لدفع أعظمهما.

وإذا تقررت هذه القاعدة فائدة الآخرة أعظم وأدوم، ولذة الدنيا أصغر وأقصر، وكذلك ألم الآخرة وألم الدنيا.

والمعقول في ذلك على الإيمان واليقين؛ فإذا قوي اليقين وباشر القلب أثّر الأعلى على الأدنى في جانب اللذة، واحتمال الألم الأسهل على الأصعب. والله المستعان.

٢٩١""",
  ),
  Fwaid(
    id: '133',
    name: """ فائدة""",
    text:
        """ قوله تعالى: ﴿رَبِّ إِنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ﴾ [الأنبياء: ٨٣]. جمع في هذا الدعاء بين: حقيقة التوحيد، وإظهار الفقر والفاقة إليه ربه، ووجود طعم المحبة في التملق له، والإقرار له بصفة الرحمة، وأنه أرحم الراحمين، والتوسل إليه بصفاته سبحانه، وشدة حاجته وفقره. ومن وجد المبتلى هذا كشف عنه بلواه.

وقد جُرِّبَ أنه من قالها سبع مرات – ولا سيما مع هذه المعرفة – كشف الله ضره.""",
  ),
  Fwaid(
    id: '134',
    name: """فائدة """,
    text:
        """ قوله تعالى عن يوسف نبيه: إنه قال: ﴿أَنتَ وَلِيِّي فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾ [يوسف: ١٠١]. جمعت هذه الدعوة: الإقرار بالتوحيد، والاستسلام للرب، وإظهار الافتقار إليه، والبراءة من موالاة غيره سبحانه، وكون الوفاة على الإسلام أجل غاية العبد، وأن ذلك بيد الله لا بيد العبد، والاعتزاز بالسعادة، وطلب مرافقة السعداء.""",
  ),
  Fwaid(
    id: '135',
    name: """فائدة """,
    text:
        """قول الله تعالى: ﴿وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُ﴾ [الحجر: ٢١] متضمن لكنز من الكنوز، وهو أن كل شيء لا يُطلب إلا ممن عنده خزائنه، ومفاتيح تلك الخزائن بيده، وإن طلبه من غيره طلبه ممن ليس عنده ولا يقدر عليه.

وقوله: ﴿وَإِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ﴾ [النجم: ٤٢] متضمن لكنز عظيم، وهو أن كل مراد إن لم يُرد لأجله فهو مضمحل منقطع، فإنه ليس وراء الله مراد يُقصد إليه، وليس المنتهى إلا إلى الذي انتهت إليه الأمور كلها، فانتهت إلى خلقه ومشيئته وحكمته وعلمه؛ فهو غاية كل مطلوب، وكل محبوب لا يُحب لأجله فمحبته عناء وعذاب، وكل عمل لا يُراد لأجله فهو ضائع وباطل، وكل قلب لا يصل إليه فهو شقي محجوب عن سعادته وفلاحه.

فاجتمع ما يُراد منه كله في قوله: ﴿وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُ﴾، واجتمع ما يُراد إليه كله في قوله: ﴿وَإِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ﴾؛ فليس وراءه سبحانه غاية تُطلب، وليس دونه نهاية يُنتهى.

وتحت هذا سر عظيم من أسرار التوحيد، وهو أن القلب لا يستقر ولا يطمئن ولا يسكن إلا بالوصول إليه، وكل ما سواه مما يُحب ويُراد فمراد لغيره، وليس المراد المحبوب لذاته إلا واحدًا إليه المنتهى، ويستحيل أن يكون المنتهى إلى اثنين؛ كما يستحيل أن يكون ابتداء المخلوقات من اثنين.

فكل ما كان انتهاء محبته ورغبته وإرادته وطاعته إلى غيره بطل عليه ذلك، وزال عنه وفرغ ما كان إليه، ومن كان انتهاء محبته ورغبته وطاعته إليه فهو سبحانه نظر بنعمه ولذته وبهجته وسعادته أبد الآباد.

العبد دائمًا متقلب بين أحكام الأوامر وأحكام النوازل؛ فهو محتاج:
– بل مضطر – إلى العون عند الأوامر، وإلى اللطف عند النوازل.
وعلى قدر قيامه بالأوامر يحصل له من اللطف عند النوازل؛ فإن كمال القيام بالأوامر ظاهرًا وباطنًا ناله اللطف ظاهرًا وباطنًا، وإن قام بعضهما دون حقائقها وبواطنها ناله من اللطف في الظاهر وقل نصيبه من اللطف في الباطن.

فإن قلت: وما اللطف الباطن؟
فهو ما يحصل للقلب عند النوازل من السكينة والطمأنينة، وزوال القلق والاضطراب والجزع؛ فيستحلي بين يدي سيده ذليلا له مستكينًا ناظرًا إليه بقلبه ساكنًا إليه بروحه وسره، وقد يشغله مشاهدة لطفه به عن شدة ما هو فيه من الألم، وقد يغيب عن شهود ذلك بمعرفته بحسن اختياره له، وأنه عبد محض يجري عليه سيده أحكامه رضى أو سخط؛ فإن رضي نال الرضى، وإن سخط فحظه السخط.

فهذا اللطف الباطن ثمرة تلك المعاملة الباطنة؛ يزيد بزيادتها، وينقص بنقصانها. """,
  ),
  Fwaid(
    id: '136',
    name: """ فائدة جليلة""",
    text: """ لا يزال العبد منقطعًا عن الله حتى تتصل إرادته ومحبته بوجهه الأعلى.

والمراد بهذا الاتصال: أن تنتهي المحبة إليه وتتعلق به وحده، فلا يحبه شيء دونه، وأن تتصل المعرفة بأسمائه وصفاته وأفعاله، فلا يطلب نورها ظلمة التعطيل؛ كما لا يطلب نور المحبة ظلمة الشرك، وأن يتصل ذكره به سبحانه؛ كما يزول بين الذاكر والمذكور حجاب الغفلة والغفلة، فإن الذكر إلى غير المذكور محال؛ فحينئذٍ يتصل الذكر به.

ويتصل العمل بأوامره ونواهيه؛ فيفعل الطاعة لأنه أمر بها وأحبها، ويترك المناهي لكونه نهى عنها وأبغضها؛ فهذا معنى اتصال العمل بأمره ونهيه. وحقيقته زوال العلل الباعثة على الفعل والترك من الأغراض والحظوظ العاجلة.

ويتصل التوكل والحب به؛ بحيث يصير واثقًا به سبحانه، مطمئنًا إليه، راضيًا بحسن تدبيره له، غير متهم له في حال من الأحوال.

ويتصل فقره وفاقته به سبحانه دون من سواه.

ويتصل خوفه ورجاؤه وفرحه وسروره وانتهاجه به وحده، فلا يخاف غيره ولا يرجوه ولا يفرح به كل الفرح ولا يبشر به غاية السرور، وإن ناله بالمخلوق بعض الفرح والسرور؛ فليس الفرح التام والسرور الكامل والانتهاج والنعيم وقرة العين وسكون القلب إلا به سبحانه، وما سواه إن أعان على هذا المطلوب فرح به وسرّ به، وإن حجب عنه حزن به وتوحش منه واضطرب القلب بحصوله أو بحصوله أحق منه؛ فإن فرح به فلا فرح ولا سرور إلا به، وما أوصل إليه وأعان عليه فهو فرح وسرور، وبانقطاعه أعظم انقطاع الفرح والسرور؛ فهو الإسلام والإيمان والقرآن، كما فسره الصحابة والتابعون.

والمقصود أن من اتصلت له هذه الأمور بالله سبحانه فقد وصل، وإلا فهو مقطوع عن ربه، متصل بحظه ونفسه، ملبس عليه في معرفته وإرادته وسلوكه.""",
  ),
  Fwaid(
    id: '137',
    name: """ قاعدة جليلة""",
    text: """ فكرت في هذا الأمر؛ فإذا أصله:
أن تعلم أن النعم كلها من الله وحده؛ نعم الطاعات ونعم اللذات، فتفرغ إليه في إلباسك ذكرها وشكرها كما قال تعالى: ﴿وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ﴾ [النحل: ٥٣]، وقال: ﴿فَٱذۡكُرُواْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ﴾ [الأعراف: ٦٩]، وقال: ﴿وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗ﴾ [لقمان: ٢٠]، وقال: ﴿وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ﴾ [النحل: ١٨].

فإذا عرفت أن تلك النعم كلها من الله وحده، وأن شكرها ذكرها لا بلسانك فقط، بل بالقلب واللسان والجوارح؛ وأن الذنوب من خذلانه وتخليته بين عبده ونفسه، وأنه لو لم يكشف ذلك عن عبده لما سأل إلى كشفه عن نفسه؛ فإذا صرت مضطرًا إلى التضرع إليه أن يدفع عنك أسبابها حتى لا تصدر منك، وإذا وقعت فبحكم المقدر ومقتضى البشرية فهو مضطر إلى التضرع والدعاء أن يدفع عنه عواقبها.

فلا ينفك العبد عن ضرورة وردية بين هذه الأصول الثلاثة [٢٠٠]: ولا فلاح له إلا بها: الشكر، وطلب العافية، والتوبة النصوح.

ثم فكرت فإذا مدار ذلك على الرغبة والرهبة، وليس بيد العبد، بل بيد مقلب القلوب ومصرفها كيف يشاء؛ فإن وفق عبده أقبل بقلبه إليه، وأملاه رغبة ورهبة، وإن خذله تركه ونفسه، ولم يأخذ بقلبه إليه، ولم يشأ ذلك، وما شاء الله كان ولم يشأ لم يكن.

ثم فكرت: هل للتوفيق والخذلان سبب؟ أم هما بمحض المشيئة لا سبب لهما؟ فإذا سببهما أهلية المحل وعدمها؛ فهو سبحانه خالق الاستعداد في الاستعداد والقبول أعظم تفاوت؛ فالجمادات لا تقبل ما يقبله الحيوان، وكذلك الحيوان لا يقبل ما يقبله الناطق، فالناطق لا يقبل ما يقبله الملهم، وهو متفاوت في القبول أعظم تفاوت، وكذلك الحيوان البهيم متفاوت في القبول، لكن ليس بين النوع الواحد من التفاوت كما بين النوع الإنساني.

فإذا كان المحل قابلاً للنعمة بحيث يعرفها، ويعرف قدرها وخطرها، ويشكر المنعم بها، ويثني عليه بها، ويعظمها عليه، ويعلم أنها من محض الجود وعين المنة من غير أن يكون هو مستحقًا لها ولا هي له به، وإنما هي من جوده وحده؛ فما دامت متصلة بإخلاصها وتعظيمها وحمدها، فهو من محض جوده، ومتى عرف قدرها عليه، وقصر في شكرها عجزًا وضعفًا وتفريطًا، وعلم أنه إن أدماها عليه ذلك فهو محض صدقه وفضله وإحسانه، وإن سلبها إياه فهو أهل لذلك ومستحق له؛ وكلما ازداد من نعمه ازداد ذلًا وانكسارًا وخضوعًا بين يديه، وقلبًا لشكره وخشيته له سبحانه أن يسلبه إياها لعدم توفيقه شكرها، كما سلب نعمة غيره لم يعرفها ولم يرعها حق رعايتها.

فإن لم يشكر نعمة وقابلها بضد ما يليق أن يقابل به سلبه إياها ولا بد.

قال تعالى: ﴿وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ﴾ [الأنعام: ٥٥]، وهم الذين عرفوا قدر النعمة وقابلوها بالجحود وأثروا على علمهم بها وأحبوا وقاموا بشكرها.

وقال تعالى: ﴿وَإِذَا رَءَا۟ءَهُم مِّنۡهُمۡ قَالُوٓاْ أَن لَّوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٖ﴾ [الأنعام: ١٢٤].""",
  ),
  Fwaid(
    id: '138',
    name: """ فصل""",
    text:
        """ وسبب الخذلان عدم صلاحية المحل وأهليته وقبوله للنعمة؛ بحيث لو وافته النعم لقال: هذا لي! وإنما أوتيته لأني أهله ومستحقه! كما قال تعالى: ﴿هَٰذَا لِي﴾ [فصلت: ٥٠]، ﴿إِنَّمَا أُوتِيتُهُ عَلَىٰ عِلۡمٍ عِندِي﴾ [القصص: ٧٨] أي على علم عندي أستحق ذلك، وأستوجب استيلاءه. قال الفراء (١): أي على فضل عليّ عندي. وقال مقاتل: يقول على خير أعطانيه الله عندي. وذكر عبد الله بن الحارث بن نوفل عن سليمان بن داود فيما أوتي من الملك، ثم قرأ قوله تعالى: ﴿هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ أَأَشۡكُرُ أَمۡ أَكۡفُرُ﴾ [النمل: ٤٠]، ولم يقل: هذا من كرامتي! بل ذكر قارون وقوله: ﴿إِنَّمَا أُوتِيتُهُ عَلَىٰ عِلۡمٍ عِندِي﴾ [القصص: ٧٨]، يعني: أن سليمان أوتيه من الله ففضله الله عليه ومنه، وإن قارون أوتي ذلك من نفسه واستحقه.

وكذلك قوله سبحانه: ﴿وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي﴾ [فصلت: ٥٠]، أي: أنا أهله وحقيق به؛ فاختصاصي به كاختصاص المالك بملكه.

والمؤمن يرى ذلك ملكًا لربه وفضلًا منه به على عبده من غير استحقاق منه، بل صدقة تصدق بها على عبده لا أن يتصدق بها؛ فلو منعه إياها لم يكن منعه شيئًا هو يستحقه عليه.

فإذا شهد ذلك رأى فيه أملاً واستحقاقًا، فأصابته نفسه، ووظفت النعمة، وعملت بها، واستعان بها، واستطالت على غيره، فكان حظها من الفرح والبطر كما قال تعالى: ﴿وَإِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ﴾ [الشورى: ٤٨]، وقوله: ﴿لَيَفۡرَحَ فَرَحٗا﴾ [هود: ١٠]، فالفرح والبطر عند الابتلاء بالنعمة، واستبدال بحمده وشكره، والثناء عليه أن كشف عنه البلاء قوله: ﴿هَٰذَا لِي﴾، ولو أنه قال: أنعمت عليّ برحمتك وفضلك ومنك، لم يكن هذا كفرًا، لكنه فعل فعل من لم تنكشف له النعمة ونسبها إلى نفسه بفرح وفرح وانخدار.

فإذا علم الله سبحانه هذا من قلب عبد فذلك من أعظم أسباب خذلانه وتخليته؛ فإن محله لا تناسبه النعمة المطلقة، قال تعالى: ﴿وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَ﴾ [الإسراء: ٥٩]، ﴿لَا يَهۡدِي ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ﴾ [غافر: ٢٨]، ﴿لَا يَهۡدِي ٱللَّهُ مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ﴾ [الزمر: ٣]، فأخبر سبحانه أن محلهم غير قابل لنعمه، ومع عدم القبول فهم مانع آخر يمنع وصولها إليهم، وهو توليهم وإعراضهم إذا عرضت عليهم.

ومما ينبغي أن يعلم أن أسباب الخذلان من بقاء النفس على ما خلقت عليه في الأصل وإهمالها وتخليتها؛ فأسباب الخذلان منها وفيها، وأسباب التوفيق من جعل الله سبحانه لها قابلة للنعمة، فأسباب التوفيق من فضله، وهو الخالق لهؤلاء وهؤلاء، كما خلق الأرض قابلة للبذور، وهذه غير قابلة لها، وخلق الشجر، وهذه تقبل الثمرة وهذه لا تقبلها، وخلق النحلة قابلة لأن يخرج من بطونها شراب مختلف ألوانه، والزنبور غير قابل لذلك، وخلق الأرواح الطيبة قابلة لذكره وشكره، ومحبته وإجلاله وتعظيمه وتوحيده ونصيحة عباده، وخلق الأرواح الخبيثة غير قابلة لذلك بل ضده، وهو الحكيم العليم.""",
